@if($students->isEmpty())<div class="production-empty compact"><h3>{{ $search?'No matching students':'Search the Student Registry' }}</h3><p>Production requests can only be created for an existing student identity.</p></div>@else<form method="POST" action="{{ route('production.store') }}" class="request-form">@csrf<div class="student-choice-list">@foreach($students as $student)<label class="student-choice"><input type="radio" name="student_id" value="{{ $student->id }}" required @checked(old('student_id')==$student->id)><span><strong>{{ $student->full_name }}</strong><small>{{ $student->student_number }} · {{ $student->latestEnrollment?->program?->code??'No enrollment' }} · {{ $student->latestEnrollment?->year_level??'—' }}</small>@if($student->idCards->whereNotIn('status',[\App\Enums\CardStatus::Cancelled,\App\Enums\CardStatus::Revoked])->isNotEmpty())<em>Existing ID record found — replacement reason required when applicable.</em>@endif</span></label>@endforeach</div><div class="request-fields"><label><span>Relevant Enrollment</span><select name="student_enrollment_id"><option value="">Use latest enrollment</option>@foreach($students as $student)@foreach($student->enrollments as $enrollment)<option value="{{ $enrollment->id }}" data-student="{{ $student->id }}">{{ $student->student_number }} · {{ $enrollment->academicTerm?->academicYear?->name }} {{ $enrollment->academicTerm?->name }} · {{ $enrollment->program?->code }}</option>@endforeach@endforeach</select></label><label><span>Issuance Reason</span><select name="issuance_type" required><option value="">Select reason</option>@foreach(['initial'=>'First ID','replacement'=>'Replacement ID','damaged'=>'Damaged ID','lost'=>'Lost ID','reissue'=>'Approved Reissuance','other'=>'Other Authorized Reason'] as $value=>$label)<option value="{{ $value }}" @selected(old('issuance_type')===$value)>{{ $label }}</option>@endforeach</select></label><label class="full"><span>Internal Notes</span><textarea name="internal_notes" rows="3" maxlength="1000">{{ old('internal_notes') }}</textarea></label></div><div class="production-actions"><a class="btn text" href="{{ route('production.index') }}">Cancel</a><button class="btn primary">Create Request</button></div></form>@endif</section>
