@push('scripts')<script>(()=>{const radios=[...document.querySelectorAll('input[name="student_id"]')],select=document.querySelector('select[name="student_enrollment_id"]');const sync=()=>{const id=radios.find(r=>r.checked)?.value;[...select.options].forEach((option,index)=>{if(!index)return;const match=option.dataset.student===id;option.hidden=!match;option.disabled=!match});if(select.selectedOptions[0]?.disabled)select.value=''};radios.forEach(r=>r.addEventListener('change',sync));sync()})();</script>@endpush